// Independent image registration for each planar face. No global wall homography.
export function project(H,x,y){const z=H[6]*x+H[7]*y+H[8];if(Math.abs(z)<1e-8)return null;return [(H[0]*x+H[1]*y+H[2])/z,(H[3]*x+H[4]*y+H[5])/z];}
export function validQuad(q,w,h){if(q.some(p=>!p||p.some(v=>!Number.isFinite(v))))return false;let sign=0,area=0;for(let i=0;i<4;i++){const a=q[i],b=q[(i+1)%4],c=q[(i+2)%4],cross=(b[0]-a[0])*(c[1]-b[1])-(b[1]-a[1])*(c[0]-b[0]);if(Math.abs(cross)<1||sign&&Math.sign(cross)!==sign)return false;sign=Math.sign(cross);area+=a[0]*b[1]-a[1]*b[0];if(Math.abs(a[0])>w*3||Math.abs(a[1])>h*3)return false;}return Math.abs(area)/2>w*h*.015&&Math.abs(area)/2<w*h*4;}
export class FaceTracker{
 constructor(cv){this.cv=cv;this.orb=new cv.ORB();this.matcher=new cv.BFMatcher(cv.NORM_HAMMING,false);this.refs=[];}
 features(gray){const {cv}=this,kp=new cv.KeyPointVector(),des=new cv.Mat(),mask=new cv.Mat();try{this.orb.detectAndCompute(gray,mask,kp,des);return {kp,des};}catch(e){kp.delete();des.delete();throw e;}finally{mask.delete();}}
 add(id,gray){const f=this.features(gray);this.refs.push({id,width:gray.cols,height:gray.rows,...f});return f.kp.size();}
 locate(gray){const {cv}=this,current=this.features(gray),found=[];try{if(current.des.rows<12)return found;for(const ref of this.refs){if(ref.des.rows<12)continue;const matches=new cv.DMatchVectorVector();let src,dst,inliers,H;try{this.matcher.knnMatch(ref.des,current.des,matches,2);const a=[],b=[],seen=new Set();for(let i=0;i<matches.size();i++){const pair=matches.get(i);try{if(pair.size()<2)continue;const one=pair.get(0),two=pair.get(1);if(one.distance>=two.distance*.7||one.distance>65||seen.has(one.trainIdx))continue;seen.add(one.trainIdx);const p=ref.kp.get(one.queryIdx).pt,q=current.kp.get(one.trainIdx).pt;a.push(p.x,p.y);b.push(q.x,q.y);}finally{pair.delete();}}if(a.length<24)continue;src=cv.matFromArray(a.length/2,1,cv.CV_32FC2,a);dst=cv.matFromArray(b.length/2,1,cv.CV_32FC2,b);inliers=new cv.Mat();H=cv.findHomography(src,dst,cv.RANSAC,3,inliers,2000,.995);if(H.empty())continue;const matrix=Array.from(H.data64F),good=[],errors=[];for(let i=0;i<inliers.rows;i++)if(inliers.data[i]){const p=project(matrix,a[i*2],a[i*2+1]);if(!p)continue;good.push([a[i*2]/ref.width,a[i*2+1]/ref.height]);errors.push(Math.hypot(p[0]-b[i*2],p[1]-b[i*2+1]));}if(good.length<12||good.length/(a.length/2)<.55)continue;const span=axis=>Math.max(...good.map(p=>p[axis]))-Math.min(...good.map(p=>p[axis]));if(span(0)<.2||span(1)<.2)continue;errors.sort((a,b)=>a-b);if(errors[Math.floor(errors.length/2)]>2.5)continue;const quad=[[0,0],[ref.width,0],[ref.width,ref.height],[0,ref.height]].map(p=>project(matrix,...p));if(!validQuad(quad,gray.cols,gray.rows))continue;found.push({id:ref.id,H:matrix,width:ref.width,height:ref.height,quad,inliers:good.length});}finally{matches.delete();src?.delete();dst?.delete();inliers?.delete();H?.delete();}}return found;}finally{current.kp.delete();current.des.delete();}}
 dispose(){this.refs.forEach(r=>{r.kp.delete();r.des.delete()});this.refs=[];this.orb.delete();this.matcher.delete();}
}
